<script setup>
import{onMounted,ref,watch}from'vue';import{useRoute,useRouter}from'vue-router';import{api}from'../api.js';import{useAuthStore}from'../stores/auth.js';import{useConfirmationStore}from'../stores/confirmation.js';import{apiErrorMessage}from'../stores/notifications.js';import AdminNav from'../components/AdminNav.vue';import SkeletonRows from'../components/SkeletonRows.vue';import PlayerAvatar from'../components/PlayerAvatar.vue';import AppModal from'../components/AppModal.vue';import CompactPagination from'../components/CompactPagination.vue'
const auth=useAuthStore(),confirmation=useConfirmationStore(),route=useRoute(),router=useRouter(),users=ref([]),meta=ref({}),loading=ref(true),error=ref(''),busy=ref(null),search=ref(String(route.query.search??'')),transferTarget=ref(null);let timer
const labels={guild_leader:'ГЛ',micro_guild_leader:'Микро-ГЛ',developer:'Разработчик',party_leader:'PL',member:'Участник'}
function visibleLabels(user){return Object.fromEntries(Object.entries(labels).filter(([role])=>role!=='developer'||(auth.isDeveloper&&user.id!==auth.user?.id)))}
async function load(){loading.value=true;error.value='';try{const{data}=await api.get('/api/admin/users',{params:{search:route.query.search||undefined,page:route.query.page||1}});users.value=data.data;meta.value={current_page:data.current_page,last_page:data.last_page,total:data.total};}catch(e){error.value=apiErrorMessage(e,'Не удалось загрузить пользователей.')}finally{loading.value=false}}
function apply(page=1){router.replace({query:{...(search.value?{search:search.value}:{}),...(page>1?{page}: {})}})}
function reset(){search.value='';apply()}
watch(search,()=>{clearTimeout(timer);timer=setTimeout(()=>apply(),350)});watch(()=>route.query,load,{deep:true});onMounted(load)
async function saveRoles(user,roles){busy.value=user.id;error.value='';try{const{data}=await api.patch(`/api/admin/users/${user.id}/roles`,{roles,updated_at:user.updated_at});Object.assign(user,data);await auth.fetchMe();if(!auth.canAdmin)await router.replace('/dashboard')}catch(e){error.value=apiErrorMessage(e,'Не удалось изменить права.');await load()}finally{busy.value=null}}
async function toggleRole(user,role,checked){if(busy.value)return;const current=user.roles?.length?[...user.roles]:[user.role];if(role==='guild_leader'&&checked){transferTarget.value=user;return}const roles=checked?[...new Set([...current,role])]:current.filter(value=>value!==role);if(!roles.length){error.value='У пользователя должна остаться хотя бы одна роль.';return}await saveRoles(user,roles)}
async function confirmTransfer(){const user=transferTarget.value;if(!user)return;const current=user.roles?.length?[...user.roles]:[user.role];transferTarget.value=null;await saveRoles(user,[...new Set([...current,'guild_leader'])])}
function roleDisabled(user,role){if(busy.value===user.id)return true;if(role!=='guild_leader')return false;const current=(user.roles??[user.role]).includes('guild_leader');return current||!auth.isGuildLeader}
async function action(user,type){if(busy.value)return;const options={unlink:{title:'Отвязать Discord?',message:`Персонаж «${user.player?.nickname}» и вся история сохранятся.`,confirmLabel:'Отвязать'},deactivate:{title:'Ликвидировать персонажа?',message:`«${user.player?.nickname}» исчезнет из активного состава, история сохранится.`,confirmLabel:'Ликвидировать',danger:true},activate:{title:'Восстановить персонажа?',message:`«${user.player?.nickname}» вернётся в активный состав.`,confirmLabel:'Восстановить'},delete:{title:'Удалить пользователя?',message:`Discord-пользователь @${user.discord_username} будет удалён, персонаж и история сохранятся.`,confirmLabel:'Удалить',danger:true}};if(!await confirmation.ask(options[type]))return;busy.value=user.id;error.value='';try{if(type==='unlink')await api.put(`/api/players/${user.player.id}/user`,{user_id:null});if(type==='deactivate')await api.delete(`/api/players/${user.player.id}`);if(type==='activate')await api.post(`/api/players/${user.player.id}/activate`);if(type==='delete')await api.delete(`/api/admin/users/${user.id}`);await load()}catch(e){error.value=apiErrorMessage(e,'Операция не выполнена.')}finally{busy.value=null}}
</script>

<template><section><div class="page-heading"><div><p class="eyebrow">АДМИНКА</p><h1>Пользователи и роли</h1><p class="muted">Управление аккаунтами и минимально необходимыми правами</p></div><span class="freshness">{{ loading?'Обновляем…':`Всего: ${meta.total??0}` }}</span></div><AdminNav/><div class="panel admin-users-panel"><div class="admin-user-filter"><input v-model.trim="search" class="admin-user-search" type="search" placeholder="Поиск по Discord или персонажу"><button v-if="search" @click="reset">Сбросить</button></div><div v-if="search" class="active-filters"><span>Поиск: <b>{{ search }}</b><button aria-label="Убрать поиск" @click="reset">×</button></span></div><p v-if="error" class="notice error">{{ error }} <button @click="load">Повторить</button></p><SkeletonRows v-if="loading&&!users.length" :rows="7" :columns="4"/><div v-else :class="['admin-user-list',{updating:loading}]" :aria-busy="loading"><article v-for="user in users" :key="user.id" class="admin-user-row"><PlayerAvatar class="admin-user-avatar" :player="{nickname:user.discord_display_name||user.discord_username,user}" size="small"/><div class="admin-user-identity"><strong>{{ user.discord_display_name||user.discord_username }}</strong><small>@{{ user.discord_username }}</small></div><div class="admin-user-player"><RouterLink v-if="user.player" :to="`/players/${user.player.id}`">{{ user.player.nickname }}</RouterLink><span v-else>Профиль не привязан</span><small>{{ user.player?.group?.name??(user.player?'Одиночка':'') }}</small></div><div class="admin-role-select"><span>Права доступа</span><label v-for="(label,value) in visibleLabels(user)" :key="value"><input type="checkbox" :checked="(user.roles??[user.role]).includes(value)" :disabled="roleDisabled(user,value)" @change="toggleRole(user,value,$event.target.checked)">{{ label }}</label></div><details class="admin-actions-menu"><summary>Действия</summary><div><button :disabled="!user.player||busy" @click="action(user,'unlink')">Отвязать Discord</button><button v-if="user.player?.is_active" class="danger" :disabled="busy" @click="action(user,'deactivate')">Ликвидировать</button><button v-else-if="user.player" :disabled="busy" @click="action(user,'activate')">Восстановить</button><button class="danger" :disabled="user.id===auth.user?.id||busy" @click="action(user,'delete')">Удалить пользователя</button></div></details></article><div v-if="!users.length" class="empty-state"><strong>{{ search?'По фильтрам ничего не найдено':'Пользователей пока нет' }}</strong><p>{{ search?'Сбросьте или измените активные фильтры.':'Пользователи появятся после входа через Discord.' }}</p><button v-if="search" @click="reset">Сбросить фильтры</button></div></div><CompactPagination :page="meta.current_page??1" :pages="meta.last_page??1" :disabled="loading" label="Страницы пользователей" @change="apply"/></div><AppModal :open="Boolean(transferTarget)" title="Передать права ГЛ?" :dismissible="!busy" @close="transferTarget=null"><section v-if="transferTarget" class="form-card role-transfer-modal"><p class="eyebrow">ПЕРЕДАЧА РОЛИ</p><h2>Передать права ГЛ?</h2><p>Новым ГЛ станет <strong>{{ transferTarget.player?.nickname||transferTarget.discord_display_name||transferTarget.discord_username }}</strong>.</p><p class="muted">После подтверждения роль ГЛ будет снята с вашего аккаунта. Остальные назначенные вам роли сохранятся.</p><div class="form-actions"><button class="secondary" :disabled="busy" @click="transferTarget=null">Отмена</button><button class="danger" :disabled="busy" @click="confirmTransfer">Передать роль ГЛ</button></div></section></AppModal></section></template>
